--[[
  This mod, and the poker server it uses, are both open source. You can deploy
  or fork your own if ours doesn't meet your needs:
  https://github.com/just-jane-inc/just-poker
]]
local POKER_SERVICE_ENDPOINT = nil

end -- Connection configuration



-- All JSON serialized messages received from polling are indexed by the order they are received.
local MESSAGE_QUEUE = {}

-- The event_queue's growth will outpace the rate at which events are processed.
-- An index
-- The index of the latest processed event
local CURRENT_EVENT_INDEX = 0
-- All parsed messages that are awaiting to be processed
local EVENT_QUEUE = {}


--[[
  Singleton switch/case style table mapping for JSON-decoded data.
  Processes payloads that are a table, containing the two following 
  fields, and have a mapping for the event_type:

  payload = {
    event_type = string,
    data = table
  }
  
  Anything superfluous to this is not considered. Those two fields are 
  all that must be present for a payload to be correctly processed.

  The makeup of the "data" field for each "event_type" is defined in the comment 
  for each mapped function.
]]
-- local PAYLOAD_EVENT_TYPE_FUNCTION_MAP = nil

